function validate([ranks, cars]) {
  if (!Array.isArray(ranks) || ranks.length < 1 || ranks.length > 100000) return 'ranks needs 1 to 10^5 values.';
  if (ranks.some(r => !Number.isInteger(r) || r < 1 || r > 100)) return 'Each rank is an integer from 1 to 100.';
  if (!Number.isInteger(cars) || cars < 1 || cars > 1000000) return 'cars is an integer from 1 to 10^6.';
  return null;
}

