function repairCars(ranks, cars) {
  let low = 1;
  let high = ranks[0] * cars * cars;

  while (low < high) {
    const mid = Math.floor((low + high) / 2);
    let repaired = 0;
    for (const rank of ranks) {
      repaired += Math.floor(Math.sqrt(mid / rank));
    }
    if (repaired >= cars) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return low;
}

brute:
function repairCars(ranks, cars) {
  // Mechanic i finishes their k-th car at minute rank * k * k. List every such finishing time
  // (no mechanic needs more than cars cars) and the cars-th smallest one is the answer.
  const finishes = new Float64Array(ranks.length * cars);
  let size = 0;
  for (const rank of ranks) for (let k = 1; k <= cars; k++) finishes[size++] = rank * k * k;
  finishes.sort();
  return finishes[cars - 1];
}

