function generate(rand, size) {
  const between = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'large') {
    const mode = Math.floor(rand() * 3);
    if (mode === 0) return [Array.from({ length: 2000 }, () => between(1, 100)), between(1, 1000000)];
    if (mode === 1) return [Array.from({ length: between(1, 5) }, () => between(90, 100)), between(900000, 1000000)];
    return [Array.from({ length: 2000 }, () => between(1, 3)), between(1, 2000)];
  }
  const n = between(1, 6);
  const top = [1, 5, 100][Math.floor(rand() * 3)];
  return [Array.from({ length: n }, () => between(1, top)), between(1, 12)];
}
